INSERT INTO public.team_members (member_number, slug, display_name, role_title, device, os_env, stage_label, main_practice, defense_scope, overview_summary, tools, accent_theme)
VALUES (3, '3', 'Thành viên 3 (Người 3)', 'Khai thác Tự động SQLMap, Kiểm toán CSDL (PoC 3) & Vá Mật mã học', 'Laptop Windows 2 (Ubuntu VM)', 'Ubuntu Terminal + SQLMap + Container MariaDB & PHP CLI', 'Giai đoạn 3 • SQLMap & CSDL', 'SQLMap 3 lệnh tự động & Kiểm toán hộp trắng MariaDB CLI (PoC 3)', 'Vá lỗi 1 (Băm Bcrypt cost=12) & Vá lỗi 2 (Phân quyền DB tối thiểu dvwa_svc)', 'Tự động hóa khai thác bằng chuỗi 3 lệnh SQLMap (--dbs, --tables, --dump), kiểm toán hộp trắng bảng users qua MariaDB CLI để phát hiện lỗi MD5 không Salt (CWE-759, Rainbow Table), sau đó vá trực tiếp bằng Bcrypt và tài khoản dịch vụ Least Privilege.', '["SQLMap (--batch)","MariaDB CLI (mysql -u root)","PHP CLI (password_hash)","GRANT Least Privilege"]'::jsonb, 'emerald')
