INSERT INTO public.vulnerabilities (id, cwe_id, title, cvss_vector, cvss_score, severity, poc_ref, owner_member, remediation)
VALUES ('vuln-cwe-759', 'CWE-759', 'Lưu trữ Mật khẩu băm MD5 không Salt (Unsalted One-Way Hash)', 'CVSS:3.1/AV:N/AC:L/PR:H/UI:N/S:U/C:H/I:N/A:N', 4.9, 'Medium', 'PoC 3 (admin & smithy trùng chuỗi 5f4dcc3b5aa765d61d8327deb882cf99)', 3, 'Chuyển sang băm thích ứng có Salt tự động bằng Argon2id hoặc Bcrypt (cost=12) qua password_hash() và xác thực bằng password_verify().')
