INSERT INTO public.vulnerabilities (id, cwe_id, title, cvss_vector, cvss_score, severity, poc_ref, owner_member, remediation)
VALUES ('vuln-cwe-614', 'CWE-614', 'Thiếu cờ bảo mật trên Cookie phiên (PHPSESSID & security=low)', 'CVSS:3.1/AV:N/AC:H/PR:N/UI:R/S:U/C:L/I:L/A:N', 4.2, 'Medium', 'PoC 1 (Set-Cookie thiếu HttpOnly, SameSite=Strict)', 1, 'Thiết lập đầy đủ cờ HttpOnly, Secure và SameSite=Strict cho PHPSESSID; không lưu trạng thái bảo mật (security=low) ở phía Client.')
