INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-1-1', 1, 'Tại sao trong PoC 1 chỉ cần ẩn phiên bản Apache (ServerTokens Prod) mà không sửa code PHP ngay?', 'Ẩn banner Apache khắc phục trực tiếp lỗ hổng CWE-200 (CVSS 5.3) ở tầng cấu hình máy chủ web: kẻ tấn công không biết chính xác bản 2.4.25 (Debian) để tra cứu CVE khai thác tự động. Đây là bước hạ tầng (Layer 1) trong mô hình Defense-in-Depth, bổ trợ cho phần vá code PHP của Thành viên 4.', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-1-2', 1, 'Vì sao Docker container có lúc dùng ID 215d3a734374, lúc lại dùng tên ''dvwa''?', 'Container được tạo tự động có tên ngẫu nhiên như epic_dijkstra (ID 215d3a734374). Khi nhân bản môi trường sang các máy thực hành khác, việc đặt thêm cờ --name dvwa giúp đồng bộ câu lệnh docker exec giữa tất cả các máy mà không phụ thuộc vào hash ID ngẫu nhiên.', false)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-2-1', 2, 'Tại sao trình duyệt của Burp Suite lại bỏ qua Proxy khi truy cập 127.0.0.1:8080 và localtest.me giải quyết thế nào?', 'Nhân Chromium mặc định áp dụng danh sách bỏ qua Proxy (Loopback Bypass) cho localhost và 127.0.0.1 nhằm tránh vòng lặp nội bộ. Tên miền localtest.me phân giải DNS công khai về 127.0.0.1 nhưng về mặt chuỗi tên miền lại khác localhost, buộc Chromium đẩy 100% gói tin qua cổng Proxy 8081 của Burp Suite.', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-2-2', 2, 'Khi kiểm tra Apache access.log, làm sao phân biệt được request tấn công từ cURL hay từ trình duyệt Burp?', 'Dựa vào 3 IoC cốt lõi trong mỗi dòng log: (1) Chuỗi truy vấn chứa ký tự đặc biệt mã hóa như %27, UNION, SELECT; (2) Trường User-Agent ghi rõ ''curl/...'' đối với CLI so với ''Mozilla/5.0...'' của trình duyệt tích hợp Burp; (3) Mã phản hồi HTTP và kích thước response (response dump 5 users dài hơn hẳn query thường).', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-3-1', 3, 'Nếu không dùng Salt, tại sao admin và smithy có cùng hash MD5 lại nguy hiểm hơn bình thường?', 'Khi không có Salt, hàm băm MD5 luôn tạo ra một đầu ra cố định cho cùng một đầu vào (5f4dcc3b5aa765d61d8327deb882cf99 cho ''password''). Kẻ tấn công chỉ cần tra bảng cầu vồng (Rainbow Table) 1 lần là biết ngay cả admin lẫn smithy dùng chung mật khẩu, mở rộng chiếm quyền hàng loạt.', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-3-2', 3, 'Tạo user dvwa_svc với quyền SELECT, INSERT, UPDATE có giúp chống được lỗi SQL Injection không?', 'Least Privilege không tự chặn lỗi nối chuỗi SQLi, nhưng nó giới hạn tối đa hậu quả (Blast Radius): kẻ tấn công không thể dùng quyền root để DROP TABLE, tạo user mới, hoặc đọc/ghi file hệ điều hành qua LOAD_FILE / INTO OUTFILE.', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-4-1', 4, 'Tại sao hàm mysqli_real_escape_string() trong medium.php vẫn bị SQL Injection vượt qua?', 'Hàm mysqli_real_escape_string() chỉ thêm dấu gạch chéo ngược trước các ký tự nháy đơn '', nháy kép "... Nhưng trong medium.php, biến $id đặt thẳng sau dấu bằng (WHERE user_id = $id) không có dấu nháy đơn bao quanh. Kẻ tấn công truyền payload kiểu số học như ''1 OR 1=1'' hoàn toàn không cần dùng dấu nháy đơn nên bộ lọc bị vô hiệu.', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

INSERT INTO public.qa_items (id, member_number, question, answer_summary, is_defense)
VALUES ('qa-4-2', 4, 'Tại sao trong PoC 5 phải làm thêm bước tinh chỉnh trích xuất user_token thay vì chỉ chụp ảnh mã 302 Found?', 'Mã 302 Found chỉ chứng minh lớp bảo vệ đầu tiên là Anti-CSRF checkToken() ở dòng 5 đã chạy, chưa chạm tới lớp kiểm tra $id và PDO Prepared Statements ở dòng 11–15. Phải gửi kèm user_token hợp lệ và payload id=1'' để thấy hệ thống chặn ở is_numeric() và trả về 200 OK sạch lỗi mới chứng minh trọn vẹn bản vá SQLi.', true)
ON CONFLICT (id) DO UPDATE SET
  member_number = EXCLUDED.member_number, question = EXCLUDED.question, answer_summary = EXCLUDED.answer_summary, is_defense = EXCLUDED.is_defense;

